let _enginesRoot = null;

function getEnginesRoot() {
  if (_enginesRoot && fs.existsSync(path.join(_enginesRoot, 'Prometheus-master', 'cli.lua'))) {
    return _enginesRoot;
  }
  const root = path.join(os.tmpdir(), 'mega-obf-engines-v1');
  const marker = path.join(root, '.ok');
  if (!fs.existsSync(marker)) {
    fs.mkdirSync(root, { recursive: true });
    const tgz = Buffer.from(ENGINES_B64, 'base64');
    const tgzPath = path.join(os.tmpdir(), 'mega-engines-' + process.pid + '.tgz');
    fs.writeFileSync(tgzPath, tgz);
    try {
      execFileSync('tar', ['-xzf', tgzPath, '-C', root], { stdio: 'pipe', timeout: 60000 });
      fs.writeFileSync(marker, '1');
    } finally {
      try { fs.unlinkSync(tgzPath); } catch (e) {}
    }
  }
  _enginesRoot = root;
  return root;
}

function enginePath() {
  return path.join.apply(path, [getEnginesRoot()].concat([].slice.call(arguments)));
}

function findLua() {
  const candidates = ['lua5.1', 'lua', 'lua5.2', 'lua5.3', '/usr/bin/lua5.1', '/usr/bin/lua', '/usr/local/bin/lua5.1'];
  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    if (c.indexOf('/') === 0) {
      if (fs.existsSync(c)) return c;
      continue;
    }
    try {
      const p = execSync('which ' + c, { encoding: 'utf8' }).trim();
      if (p) return p;
    } catch (e) {}
  }
  return null;
}

function findLuac() {
  const candidates = ['luac5.1', 'luac', '/usr/bin/luac5.1', '/usr/bin/luac', '/usr/local/bin/luac5.1'];
  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    if (c.indexOf('/') === 0) {
      if (fs.existsSync(c)) return c;
      continue;
    }
    try {
      const p = execSync('which ' + c, { encoding: 'utf8' }).trim();
      if (p) return p;
    } catch (e) {}
  }
  return null;
}

function runPrometheus(source, preset) {
  const lua = findLua();
  if (!lua) throw new Error('lua5.1 not installed');
  const dir = enginePath('Prometheus-master');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'prom-'));
  const input = path.join(tmp, 'in.lua');
  const output = path.join(tmp, 'out.lua');
  try {
    fs.writeFileSync(input, source, 'utf8');
    const safe = ['Minify', 'Weak', 'Medium', 'Strong'].indexOf(preset) >= 0 ? preset : 'Strong';
    execFileSync(lua, [path.join(dir, 'cli.lua'), '--preset', safe, '--out', output, input], {
      cwd: dir, timeout: 120000, maxBuffer: 25 * 1024 * 1024, stdio: ['pipe', 'pipe', 'pipe']
    });
    if (!fs.existsSync(output)) throw new Error('Prometheus no output');
    return fs.readFileSync(output, 'utf8');
  } finally {
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (e) {}
  }
}

function runIB2(source, options) {
  options = options || {};
  const dir = enginePath('ib2js', 'ib2js');
  const runJs = path.join(dir, 'run.js');
  if (!fs.existsSync(runJs)) throw new Error('IB2 missing after extract');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ib2-'));
  const input = path.join(tmp, 'input.lua');
  const output = path.join(tmp, 'output.lua');
  try {
    fs.writeFileSync(input, source, 'utf8');
    const args = [runJs, input, output];
    if (options.encryptStrings) args.push('--encrypt-strings');
    if (options.noMinify) args.push('--no-minify');
    if (options.noControlFlow) args.push('--no-control-flow');
    execFileSync(process.execPath, args, {
      cwd: dir, timeout: 120000, maxBuffer: 25 * 1024 * 1024, stdio: ['pipe', 'pipe', 'pipe']
    });
    if (!fs.existsSync(output)) throw new Error('IB2 no output');
    return fs.readFileSync(output, 'latin1');
  } finally {
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (e) {}
  }
}

function runHercules(source) {
  const lua = findLua();
  if (!lua) throw new Error('lua not installed');
  const dir = enginePath('hercules-obfuscator-source', 'src');
  const entry = path.join(dir, 'hercules.lua');
  if (!fs.existsSync(entry)) throw new Error('Hercules missing');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'herc-'));
  const input = path.join(tmp, 'in.lua');
  try {
    fs.writeFileSync(input, source, 'utf8');
    execFileSync(lua, [entry, input], {
      cwd: dir, timeout: 120000, maxBuffer: 25 * 1024 * 1024, stdio: ['pipe', 'pipe', 'pipe']
    });
    const files = fs.readdirSync(tmp).filter(function(f) { return f !== 'in.lua'; });
    if (!files.length) throw new Error('Hercules no output (may need Lua 5.2+)');
    return fs.readFileSync(path.join(tmp, files[0]), 'utf8');
  } finally {
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (e) {}
  }
}

function obfuscate(source, opts) {
  opts = opts || {};
  const engine = String(opts.engine || 'mega').toLowerCase();
  const preset = opts.preset || 'Strong';
  getEnginesRoot();

  if (engine === 'prometheus') {
    return { code: runPrometheus(source, preset), engine: 'prometheus', preset: preset };
  }
  if (engine === 'ib2') {
    return { code: runIB2(source, opts), engine: 'ib2' };
  }
  if (engine === 'hercules') {
    return { code: runHercules(source), engine: 'hercules' };
  }
  let code = runPrometheus(source, 'Strong');
  try {
    code = runIB2(code, { encryptStrings: true });
    return { code: code, engine: 'mega', steps: ['prometheus:Strong', 'ib2'] };
  } catch (e) {
    return { code: code, engine: 'prometheus', preset: 'Strong', warning: 'IB2 skipped: ' + e.message };
  }
}

module.exports = { obfuscate: obfuscate, getEnginesRoot: getEnginesRoot, findLua: findLua, findLuac: findLuac };
